/* selectMenuPivot_backup - Lee JiSeob */

WITH T (RIGHT_ID, RIGHT_NAME, MENU_ID_PIVOT, RIGHT_EXISTS) AS (
	SELECT 
		C.RIGHT_ID, E.RIGHT_NAME, C.MENU_NO AS MENU_ID_PIVOT,
		CASE WHEN C.RIGHT_ID IS NULL THEN 'N' ELSE 'Y' END AS RIGHT_EXISTS
	FROM RIGHT_MANAGE E
	LEFT JOIN RIGHT_GROUP C ON C.RIGHT_ID = E.RIGHT_ID 
)
SELECT *
FROM T PIVOT (
	MAX(RIGHT_EXISTS)
	FOR MENU_ID_PIVOT IN (
		#{pivotStr}
	)
)

